cypress_script:
describe('Text Box Form', () => {
  it('should submit the form with valid data', () => {
    cy.visit('https://demoqa.com/text-box');
    cy.get('#userName').type('John Doe');
    cy.get('#userEmail').type('john.doe@example.com');
    cy.get('#currentAddress').type('123 Main St');
    cy.get('#permanentAddress').type('456 Elm St');
    cy.get('#submit').click();
    cy.url().should('include', '/text-box');
  });

  it('should not change the URL when the form is submitted empty', () => {
    cy.visit('https://demoqa.com/text-box');
    cy.get('#submit').click();
    cy.url().should('include', '/text-box');
    cy.get('#userName').should('be.visible');
    cy.get('#userEmail').should('be.visible');
    cy.get('#currentAddress').should('be.visible');
    cy.get('#permanentAddress').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Text Box Form', () => {
  test('should submit the form with valid data', async ({ page }) => {
    await page.goto('https://demoqa.com/text-box');
    await page.fill('#userName', 'John Doe');
    await page.fill('#userEmail', 'john.doe@example.com');
    await page.fill('#currentAddress', '123 Main St');
    await page.fill('#permanentAddress', '456 Elm St');
    await page.click('#submit');
    await expect(page).toHaveURL(/.*text-box/);
  });

  test('should not change the URL when the form is submitted empty', async ({ page }) => {
    await page.goto('https://demoqa.com/text-box');
    await page.click('#submit');
    await expect(page).toHaveURL(/.*text-box/);
    await expect(page.locator('#userName')).toBeVisible();
    await expect(page.locator('#userEmail')).toBeVisible();
    await expect(page.locator('#currentAddress')).toBeVisible();
    await expect(page.locator('#permanentAddress')).toBeVisible();
  });
});
